import ctypes

class gsl_sum_levin_utrunc_workspace:
    _workspace = None
    def __init__(self, n):
        self._workspace = ctypes.c_void_p()

    @classmethod
    def allocate_and_free_workspace(cls, n):
        try:
            # Load the dynamic libraries
            libgslcblas = ctypes.CDLL="/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

            # Allocate the workspace
            _workspace = ctypes.c_void_p()
            libgsl.sum_levin_utrunc_alloc(ctypes.byref(_workspace), n)
            return True
        except Exception as e:
            print(f"Error: {str(e)}")
            return False

        finally:
            # Free the workspace, if allocated
            try:
                libgsl.sum_levin_utrunc_free(_workspace)
            except Exception as e:
                print(f"Error: {str(e)}")

    def __del__(self):
        self.deallocate()

    def deallocate(self):
        if self._workspace is not None:
            try:
                libgsl.sum_levin_utrunc_free(self._workspace)
            except Exception as e:
                print(f"Error: {str(e)}")

            self._workspace = None

