class LegendrePolynomial:
    def __init__(self, l):
        self.l = l

    def compute_legendre_derivatives(self, x):
        result = [0] * 4
        result[0] = 1
        for k in range(1, self.l + 1):
            if k == 1:
                result[1] = 3 * (2 * x)
            elif k % 2 == 1:
                result[k] = 3 * ((-1) ** ((k - 1) // 2)) * factorial(k) / (factorial((k - 1) // 2) * (2 * x + 1 - (k % 2 == 0)))
            else:
                result[k] = 3 * ((-1) ** ((k - 2) // 2)) * factorial(k) / (factorial((k - 2) // 2) * (2 * x + 1 - (k % 2 == 0)))
        return [x, result[0], result[1]]

    def __str__(self):
        return f"LegendrePolynomial(l={self.l})"

def compute_legendre_derivatives(x_values):
    legendre_polynomials = [LegendrePolynomial(10)]
    results = [[x, 0.0, 0.0] for x in x_values]
    for leg in legendre_polynomials:
        for i, x in enumerate(x_values):
            results[i][1:] = leg.compute_legendre_derivatives(x)[1:]
    return [dict(zip(['x', 'value', 'first_derivative', 'second_derivative'], result)) for result in results]

