class gsl_histogram2d_pdf:
    def __init__(self, nx, ny):
        self.nx = nx
        self.ny = ny

    def allocate(self):
        return gsl.gsl_histogram2d_pdf_alloc(self.nx, self.ny)

    def initialize(self, histogram_ptr, x_range, y_range):
        return gsl.gsl_histogram2d_pdf_init(histogram_ptr, x_range[0], x_range[1], y_range[0], y_range[1])

    def sample(self, pdf_ptr, r1, r2):
        return gsl.gsl_histogram2d_pdf_sample(pdf_ptr, r1, r2)

    def free(self, histogram_ptr):
        return gsl.gsl_histogram2d_pdf_free(histogram_ptr)

def create_histogram2d(nx, ny, bin_values, xrange, yrange):
    pdf = gsl_histogram2d_pdf(nx, ny)
    histogram_ptr = pdf.allocate()
    pdf.initialize(histogram_ptr, xrange, yrange)
    return histogram_ptr, pdf

def sample_pdf(nx, ny, bin_values, xrange, yrange, r1, r2, histogram_ptr):
    x_val = []
    y_val = []
    for _ in range(10000):
        value = gsl.gsl_histogram2d_pdf_sample(histogram_ptr, r1, r2)
        if 0 <= value < nx * ny:
            x_val.append(value % nx)
            y_val.append(int(value / nx))
    return x_val, y_val

def main():
    nx = int(input("Enter number of bins in X-axis: "))
    ny = int(input("Enter number of bins in Y-axis: "))
    bin_values = [int(x) for x in input("Enter bin values (comma-separated): ").split(',')]
    xrange = [float(x) for x in input("Enter X-range (comma-separated): ").split(',')]
    yrange = [float(y) for y in input("Enter Y-range (comma-separated): ").split(',')]
    r1, r2 = norm.rvs(loc=0, scale=1, size=10000)
    histogram_ptr, _ = create_histogram2d(nx, ny, bin_values, xrange, yrange)
    x_val, y_val = sample_pdf(nx, ny, bin_values, xrange, yrange, r1, r2, histogram_ptr)
    return dumps({"x": x_val, "y": y_val})

