        self.gsl_matrix = gaussian.gsl_matrix.ccreate(
            c_int(len(matrix)),
            c_int(len(matrix[0]))
        )
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                self.gsl_matrix.get_f(i, j-1).value = matrix[i][j]

    def __del__(self):
