class GslVectorComplex:
    def __init__(self, size):
        self.gsl_vector_complex = cblas.GSL_COMPLEX_ARRAY.create_gsl_vector_complex(c_int(size))

    def __del__(self):
        cblas.GSL_COMPLEX_ARRAY.destroy_gsl_vector_complex(self.gsl_vector_complex)

class GslEigenNonsymmWorkspace:
    def __init__(self, matrix_size):
        self.gsl_eigen_nonsymm_workspace = cblas.GSL_EIGEN_NONSYMM_WORKSPACE.create_gsl_eigen_nonsymm_workspace(c_int(matrix_size))

    def __del__(self):
        cblas.GSL_EIGEN_NONSYMM_WORKSPACE.destroy_gsl_eigen_nonsymm_workspace(self.gsl_eigen_nonsymm_workspace)

def compute_eigenvalues_nonsymm(matrix):
    matrix = GslMatrix(matrix)
    workspace = GslEigenNonsymmWorkspace(len(matrix))
    eigenvalues = cblas.GSL_EIGEN_NONSYMM.create_gsl_vector_complex(c_int(len(matrix)))
