class ComplexQrDecomposition:
    def __init__(self):
        self.gsl = CDLL("/usr/local/gsl/lib/libgsl.so", mode=RTLD_GLOBAL)
        self.gslcblas = CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=RTLD_GLOBAL)

    def perform_qr_decomposition(self, A, T):
        if not isinstance(A, np.ndarray) or not isinstance(T, np.ndarray): raise TypeError(
            "A and T must be numpy arrays")
        if len(A.shape) != 2 or len(T.shape) != 2: raise ValueError("matrices must have 2 dimensions")

        A_ptr = A.ctypes.data_as(POINTER(c_complex))
        T_ptr = T.ctypes.data_as(POINTER(c_complex))
        n = A.shape[0]
        m = A.shape[1]
        lda = A.shape[1]

        qr_decomp = self.gsl.linalg_complex_QR_decomp_r;
        qr_decomp.restype = c_int
        qr_decomp.argtypes = [POINTER(c_complex), POINTER(c_complex), POINTER(c_double),
                               c_int, c_int, c_int, c_double]
        status = qr_decomp(A_ptr, T_ptr, None, n, m, lda, 0.0)

        if status != 0: raise RuntimeError("QR decomposition failed")
        return 0

