class MovingStatsAccumulator:
    def __init__(self):
        self.queue = deque()
        self.mean = 0.0
        self.median = 0.0
        self.stddev = 0.0

    def insert(self, value):
        self.queue.append(value)
        if len(self.queue) > 10:
            self.queue.popleft()
        n = len(self.queue)
        mean = sum(self.queue)/n
        median = sorted(self.queue)[n//2]
        std_dev = (sum((x-mean)**2 for x in self.queue) / n)**0.5
        self.mean = mean
        self.median = median
        self.stddev = std_dev

    def compute_result(self):
        return {'mean': self.mean, 'median': self.median, 'stddev': self.stddev}

def moving_statistics_accumulation(data, func_param):
    accumulator = MovingStatsAccumulator()
    result = {}
    for value in data:
        accumulator.insert(value)
        result.update(accumulator.compute_result())
    return json.dumps(result)

