    else:
        weights_ptr = POINTER(c_double)(weights)

    result = gslcblas.gsl_bspline_wlssolve(x_ptr, y_ptr, len(x), ws_ptr, weights_ptr)

    return (x.tolist(), np.sum((y - np.polyval(result, x)) ** 2) / len(y))

